from functools import cmp_to_key


def run_query(rows: list[dict], query: dict) -> list[dict]:
    # 1. WHERE
    where_cond = query.get("where")
    if where_cond:
        passing_rows = []
        for r in rows:
            gv = lambda op: r[op[1]] if op[0] == "col" else op[1]
            if _eval_cond(gv, where_cond) is True:
                passing_rows.append(r)
    else:
        passing_rows = list(rows)

    # 2. Grouping and aggregates
    has_aggs = any(isinstance(item, list) for item in query["select"])

    if has_aggs:
        group_by = query.get("group_by") or []

        if group_by:
            groups: dict[tuple, list] = {}
            group_order: list[tuple] = []
            for r in passing_rows:
                key = tuple(r[col] for col in group_by)
                if key not in groups:
                    groups[key] = []
                    group_order.append(key)
                groups[key].append(r)
        else:
            group_order = [()]
            groups = {(): passing_rows}

        output = []
        for key in group_order:
            group_rows = groups[key]
            agg_cache: dict[tuple, object] = {}

            def get_agg(func, arg, _rows=group_rows, _cache=agg_cache):
                ck = (func, arg)
                if ck not in _cache:
                    _cache[ck] = _compute_agg(func, arg, _rows)
                return _cache[ck]

            out = {}
            for item in query["select"]:
                if isinstance(item, str):
                    out[item] = key[group_by.index(item)]
                else:
                    func, arg = item
                    out[f"{func}({arg})"] = get_agg(func, arg)

            if "having" in query:
                _key = key
                _gb = group_by

                def gv_having(operand):
                    if operand[0] == "col":
                        return _key[_gb.index(operand[1])]
                    elif operand[0] == "val":
                        return operand[1]
                    else:
                        return get_agg(operand[1], operand[2])

                if _eval_cond(gv_having, query["having"]) is not True:
                    continue

            output.append(out)
    else:
        output = []
        for r in passing_rows:
            out = {}
            for item in query["select"]:
                out[item] = r[item]
            output.append(out)

    # 3. DISTINCT
    if query.get("distinct"):
        seen = set()
        new_output = []
        for out in output:
            h = tuple(sorted(out.items()))
            if h not in seen:
                seen.add(h)
                new_output.append(out)
        output = new_output

    # 4. ORDER BY
    if query.get("order_by"):
        output = _sort_rows(output, query["order_by"])

    # 5. OFFSET / LIMIT
    offset = query.get("offset") or 0
    limit = query.get("limit")
    if offset:
        output = output[offset:]
    if limit is not None:
        output = output[:limit]

    return output


def _eval_cond(get_val, cond):
    op = cond[0]
    if op in ("=", "!=", "<", "<=", ">", ">="):
        a = get_val(cond[1])
        b = get_val(cond[2])
        if a is None or b is None:
            return None
        if op == "=":
            return a == b
        if op == "!=":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b
    if op == "and":
        return _sql_and(_eval_cond(get_val, cond[1]), _eval_cond(get_val, cond[2]))
    if op == "or":
        return _sql_or(_eval_cond(get_val, cond[1]), _eval_cond(get_val, cond[2]))
    if op == "not":
        return _sql_not(_eval_cond(get_val, cond[1]))
    if op == "is_null":
        return get_val(cond[1]) is None
    if op == "in":
        x = get_val(cond[1])
        lits = cond[2]
        if not lits:
            return False
        if x is None:
            return None
        has_none = False
        for lit in lits:
            if lit is None:
                has_none = True
            elif x == lit:
                return True
        return None if has_none else False
    if op == "between":
        x = get_val(cond[1])
        lo = cond[2]
        hi = cond[3]
        if x is None:
            return None
        return x >= lo and x <= hi
    raise ValueError(f"Unknown op: {op}")


def _sql_and(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _sql_or(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _sql_not(a):
    if a is None:
        return None
    return not a


def _compute_agg(func, arg, rows):
    if func == "count":
        if arg == "*":
            return len(rows)
        return sum(1 for r in rows if r[arg] is not None)
    if func == "count_distinct":
        return len({r[arg] for r in rows if r[arg] is not None})
    if func == "sum":
        vals = [r[arg] for r in rows if r[arg] is not None]
        return sum(vals) if vals else None
    if func == "min":
        vals = [r[arg] for r in rows if r[arg] is not None]
        return min(vals) if vals else None
    if func == "max":
        vals = [r[arg] for r in rows if r[arg] is not None]
        return max(vals) if vals else None
    if func == "avg":
        vals = [r[arg] for r in rows if r[arg] is not None]
        return sum(vals) // len(vals) if vals else None
    raise ValueError(f"Unknown aggregate: {func}")


def _sort_rows(rows, order_by):
    def _null_pos(nulls, direction):
        if nulls is None:
            return 0 if direction == "asc" else 2
        return 0 if nulls == "first" else 2

    def cmp(a, b):
        for key, direction, nulls in order_by:
            va = a.get(key)
            vb = b.get(key)
            if va is None and vb is None:
                continue
            if va is None or vb is None:
                pos = _null_pos(nulls, direction)
                if va is None:
                    return -1 if pos == 0 else 1
                return 1 if pos == 0 else -1
            if va < vb:
                r = -1
            elif va > vb:
                r = 1
            else:
                continue
            if direction == "desc":
                r = -r
            if r != 0:
                return r
        return 0

    return sorted(rows, key=cmp_to_key(cmp))
